import React, { useRef, useState } from 'react';
import './UserStatus.css';

function UserStatus({setPostsList, postsList}, User) {
    const [photo, setPic] = useState('')
    const [search, setSearch] = useState('')
    const addPost = (text, photo) => {
        const userName = User._firstName + User.lastName;
        const post = {
            "id": postsList.length+1,
            "userPic": User._picter,
            "name": userName,
            text,
            photo,
            "like":0,
            "comments":0
        }
        setPostsList([post, ...postsList])
    }

    return (
        <div className="status">
            <div class="card">

                <div class="row">
                    <div class="enterStatuse">

                        <img src={User._picter} className="card-img-bottom" alt="userPec"></img>
                        <div class="statusetext">
                            <input value={search} onChange={e => setSearch(e.currentTarget.value)} class="search" placeholder="What's on your mind?"
                                aria-label="Search"></input>
                        </div>
                        <div className='statusePic'>
                        <input class="form-control" value={photo} onChange={e => setPic(e.currentTarget.value)} type="file" id="formFile"></input>
                        </div>
                    </div>
                </div>
                <div class="statusButton">
                    <button type="button" class="btn btn-light" onClick={() => addPost(search, photo)}>Post</button>
                    <button type="button" class="btn btn-light">Live video</button>
                    <button type="button" class="btn btn-light">Photo/video</button>
                    <button type="button" class="btn btn-light">Feeling/activity</button>
                </div>
            </div>

        </div>
    );
}
export default UserStatus;
